// Graphite → Figma. Создаёт переменные, стили и компоненты в текущем файле.
// Запуск: Plugins → Development → Import plugin from manifest… → Graphite → Run.

const P = {}; // name → Variable
const COLL = {}; // name → { coll, modes: {name: modeId} }
const log = [];

// ---------- utils ----------
function parseColor(s) {
  s = String(s).trim();
  if (s === "transparent") return { r: 0, g: 0, b: 0, a: 0 };
  if (s.startsWith("#")) {
    const h = s.slice(1);
    return { r: parseInt(h.slice(0, 2), 16) / 255, g: parseInt(h.slice(2, 4), 16) / 255, b: parseInt(h.slice(4, 6), 16) / 255, a: h.length === 8 ? parseInt(h.slice(6, 8), 16) / 255 : 1 };
  }
  const m = s.match(/rgba?\(([^)]+)\)/);
  if (m) { const p = m[1].split(",").map(Number); return { r: p[0] / 255, g: p[1] / 255, b: p[2] / 255, a: p[3] == null ? 1 : p[3] }; }
  return null;
}
function scopesFor(name, coll) {
  if (coll === "Accent") return [];
  if (/edge$/.test(name)) return ["EFFECT_COLOR", "FRAME_FILL", "SHAPE_FILL"];
  if (/^color\/effect\//.test(name)) return ["EFFECT_COLOR"];
  if (/^color\/stock\/(low|out)$/.test(name)) return ["TEXT_FILL", "FRAME_FILL", "SHAPE_FILL"];
  if (/^color\/(text|status\/(error|warning|on-error)$|accent\/(text|on|subtle-text)|system\/text)/.test(name)) return ["TEXT_FILL", "SHAPE_FILL"];
  if (/^color\/line/.test(name)) return ["STROKE_COLOR"];
  if (/^color\//.test(name)) return ["FRAME_FILL", "SHAPE_FILL"];
  if (/^(space|layout)\//.test(name)) return ["GAP"];
  if (/^radius\//.test(name)) return ["CORNER_RADIUS"];
  if (/^size\//.test(name)) return ["WIDTH_HEIGHT"];
  if (/^type\/size/.test(name)) return ["FONT_SIZE"];
  if (/^type\/weight/.test(name)) return ["FONT_WEIGHT"];
  if (/^type\/line-height/.test(name)) return ["LINE_HEIGHT"];
  if (/^type\/family/.test(name)) return ["FONT_FAMILY"];
  return [];
}
// iOS code syntax — ТОЛЬКО по объявленным парам, из PAIRS_IOS.
//
// Прежняя редакция собирала имя регулярками и печатала 135 имён,
// из которых в Swift не существовало НИ ОДНОГО (замер 13.10.2026):
//   color/fill/1 -> Color("fill.1")  — форма АССЕТ-КАТАЛОГА, которой
//                                      у Togo нет вовсе: цвет живёт
//                                      Color(Dyn(dark:light:darkHC:lightHC:))
//   space/12     -> Space.s12        — почти верно и всё равно мимо:
//                                      в коде это Token.Space.s12,
//                                      bare-формы нет ни одной
//   type/*, motion/*, accent/*       — не печаталось вовсе, 64 переменные
//
// Это единственное место, которое читает дизайнер в Dev Mode. Пустой
// code syntax честен, выдуманный — нет: проверить его там нечем.
//
// PAIRS_IOS собирает Tools/пары_ios.py из объявленных пар и СВЕРЯЕТ
// каждое имя с TogoShared/Generated/Tokens.generated.swift. Пара,
// которую никто не объявил, сюда не попадает: совпадение по значению
// основанием не является — size/toggle-h и size/clear оба 36.
function iosName(name) {
  return PAIRS_IOS[name] || null;
}

// ---------- 1. variables ----------
async function buildVariables() {
  const existing = await figma.variables.getLocalVariableCollectionsAsync();
  for (const c of DATA.collections) {
    let coll = existing.find((x) => x.name === c.name);
    if (!coll) coll = figma.variables.createVariableCollection(c.name);
    const modes = {};
    coll.renameMode(coll.modes[0].modeId, c.modes[0]);
    modes[c.modes[0]] = coll.modes[0].modeId;
    for (const m of c.modes.slice(1)) {
      const found = coll.modes.find((x) => x.name === m);
      if (found) { modes[m] = found.modeId; continue; }
      try { modes[m] = coll.addMode(m); }
      catch (e) { log.push("Режим «" + m + "» в «" + c.name + "» не создан: тариф Figma ограничивает число режимов. Значения взяты из «" + c.modes[0] + "»."); }
    }
    COLL[c.name] = { coll, modes };
  }
  const allVars = await figma.variables.getLocalVariablesAsync();
  // pass 1: create
  for (const c of DATA.collections) {
    const { coll } = COLL[c.name];
    for (const v of c.variables) {
      const type = v.t === "COLOR" ? "COLOR" : v.t === "FLOAT" ? "FLOAT" : "STRING";
      let variable = allVars.find((x) => x.name === v.n && x.variableCollectionId === coll.id);
      if (!variable) variable = figma.variables.createVariable(v.n, coll, type);
      variable.scopes = scopesFor(v.n, c.name);
      if (v.css) variable.setVariableCodeSyntax("WEB", "var(" + v.css + ")");
      const ios = iosName(v.n); if (ios) variable.setVariableCodeSyntax("iOS", ios);
      if (c.name === "Accent") variable.hiddenFromPublishing = true;
      P[v.n] = variable;
    }
  }
  // pass 2: values
  for (const c of DATA.collections) {
    const { modes } = COLL[c.name];
    for (const v of c.variables) {
      const variable = P[v.n];
      for (const [m, id] of Object.entries(modes)) {
        let val = v.v[m] !== undefined ? v.v[m] : v.v[c.modes[0]];
        if (val && typeof val === "object" && val.alias) {
          const target = P[val.alias];
          if (target) variable.setValueForMode(id, figma.variables.createVariableAlias(target));
          continue;
        }
        if (variable.resolvedType === "COLOR") { const col = parseColor(val); if (col) variable.setValueForMode(id, col); else variable.setValueForMode(id, { r: 0, g: 0, b: 0, a: 0 }); }
        else if (variable.resolvedType === "FLOAT") variable.setValueForMode(id, typeof val === "number" ? val : parseFloat(val) || 0);
        else variable.setValueForMode(id, String(val));
      }
    }
  }
}

// ---------- 2. fonts & styles ----------
const F = {};
async function tryFont(list) { for (const f of list) { try { await figma.loadFontAsync(f); return f; } catch (e) {} } return null; }
async function loadFonts() {
  F.reg = await tryFont([{ family: "SF Pro Text", style: "Regular" }, { family: "SF Pro", style: "Regular" }, { family: "Inter", style: "Regular" }]);
  F.semi = await tryFont([{ family: "SF Pro Text", style: "Semibold" }, { family: "SF Pro", style: "Semibold" }, { family: "Inter", style: "Semi Bold" }]) || F.reg;
  F.round = await tryFont([{ family: "SF Pro Rounded", style: "Light" }, { family: "SF Pro", style: "Light" }, { family: "Inter", style: "Light" }]) || F.reg;
  F.icon = await tryFont([{ family: "Material Symbols Rounded", style: "Light" }, { family: "Material Symbols Rounded", style: "Regular" }]);
  if (F.reg.family === "Inter") log.push("SF Pro не установлен — текстовые стили на Inter. Установите SF Pro с developer.apple.com/fonts и переключите семейство в стилях.");
  if (!F.icon) log.push("Шрифт Material Symbols Rounded не установлен — иконки показаны кружками. Установите его с fonts.google.com/icons, имена иконок уже в слоях.");
}
const TS = {};
const TYPE = [
  ["Large Title", 34, "reg", 41], ["Title 1", 28, "reg", 34], ["Title 2", 22, "reg", 28], ["Title 3", 20, "reg", 25],
  ["Headline", 17, "semi", 22], ["Body", 17, "reg", 22], ["Callout", 16, "reg", 21], ["Subheadline", 15, "reg", 20],
  ["Footnote", 13, "reg", 18], ["Caption 1", 13, "reg", 18], ["Caption 2", 13, "reg", 18],
  ["Callout Emphasized", 16, "semi", 21], ["Subheadline Emphasized", 15, "semi", 20], ["Footnote Emphasized", 13, "semi", 18], ["Body Emphasized", 17, "semi", 22], ["Title 3 Emphasized", 20, "semi", 25], ["Screen Title", 40, "round", 42, "Togo"],
  ["Number Hero", 96, "round", 96], ["Number Hero Pad", 112, "round", 100], ["Number XL", 80, "round", 80], ["Number L", 56, "round", 56], ["Number M", 44, "round", 44], ["Number S", 30, "round", 30],
  ["Reading", 72, "round", 72, "Numbers"], ["Reading compact", 34, "round", 34, "Numbers"], ["Unit", 20, "round", 24, "Numbers"], ["Unit S", 15, "round", 20, "Numbers"], ["Footnote Rounded", 13, "round", 18, "Numbers"],
  ["Wordmark", 28, "round", 34, "Togo"], ["Large Title Rounded", 34, "round", 38, "Togo"], ["Title 2 Rounded", 22, "round", 28, "Togo"],
];
const TYPE_VAR = { "Body Emphasized": "body", "Title 3 Emphasized": "title-3", "Footnote Emphasized": "footnote", "Number Hero": "number-hero", "Number Hero Pad": "number-hero-pad", "Large Title Rounded": "large-title", "Title 2 Rounded": "title-2", "Callout Emphasized": "callout", "Subheadline Emphasized": "subheadline", "Large Title": "large-title", "Title 1": "title-1", "Title 2": "title-2", "Title 3": "title-3", Headline: "headline", Body: "body", Callout: "callout", Subheadline: "subheadline", Footnote: "footnote", "Caption 1": "caption-1", "Caption 2": "caption-2", "Number XL": "number-xl", "Number L": "number-l", "Number M": "number-m", "Number S": "number-s" };
async function buildStyles() {
  const ex = await figma.getLocalTextStylesAsync();
  for (const [name, size, w, lh, group] of TYPE) {
    const full = (group || (name.startsWith("Number") ? "Numbers" : "iOS")) + "/" + name;
    let s = ex.find((x) => x.name === full) || figma.createTextStyle();
    s.name = full; s.fontName = F[w]; s.fontSize = size; s.lineHeight = { value: lh, unit: "PIXELS" };
    if (name.startsWith("Number")) s.letterSpacing = { value: -2, unit: "PERCENT" };
    if (name.startsWith("Reading")) s.letterSpacing = { value: -3.5, unit: "PERCENT" };
    const v = P["type/size/" + TYPE_VAR[name]]; if (v) { try { s.setBoundVariable("fontSize", v); } catch (e) {} }
    TS[name] = s;
  }
  const exE = await figma.getLocalEffectStylesAsync();
  const mk = (name, effects) => { let s = exE.find((x) => x.name === name) || figma.createEffectStyle(); s.name = name; s.effects = effects; return s; };
  // Цвет каждой тени привязан к color/effect/*: в тёмной — только волосяная грань, в светлой — тени, в HC — обводка.
  const fx = (type, y, blur, spread, v) => { let e = { type, color: { r: 0, g: 0, b: 0, a: 0 }, offset: { x: 0, y }, radius: blur, spread, visible: true, blendMode: "NORMAL" }; if (type === "DROP_SHADOW") e.showShadowBehindNode = false; try { e = figma.variables.setBoundVariableForEffect(e, "color", P[v]); } catch (x) {} return e; };
  TS.elev1 = mk("Elevation/1 · карточки и строки", [fx("INNER_SHADOW", 0, 0, 1, "color/effect/hairline-1"), fx("DROP_SHADOW", 0, 0, 1, "color/effect/ring-1"), fx("DROP_SHADOW", 1, 2, 0, "color/effect/shadow-1"), fx("DROP_SHADOW", 6, 16, 0, "color/effect/shadow-1")]);
  TS.elev2 = mk("Elevation/2 · плавающие", [fx("INNER_SHADOW", 0, 0, 1, "color/effect/hairline-2"), fx("DROP_SHADOW", 0, 0, 1, "color/effect/ring-2"), fx("DROP_SHADOW", 10, 30, 0, "color/effect/shadow-2")]);
  TS.glass = mk("Glass/Blur 24", [{ type: "BACKGROUND_BLUR", radius: 24, visible: true }]);
}

// ---------- 3. builders ----------
function setFx(node, id) { try { node.effectStyleId = id; } catch (e) { node.setEffectStyleIdAsync(id); } }
function bindFill(node, name) {
  const v = P[name]; if (!v) { node.fills = []; return; }
  node.fills = [figma.variables.setBoundVariableForPaint({ type: "SOLID", color: { r: 0, g: 0, b: 0 } }, "color", v)];
}
function bindStroke(node, name, w = 1) {
  const v = P[name]; if (!v) return;
  node.strokes = [figma.variables.setBoundVariableForPaint({ type: "SOLID", color: { r: 0, g: 0, b: 0 } }, "color", v)];
  node.strokeWeight = w; node.strokeAlign = "INSIDE";
}
function bindNum(node, field, name, fallback) {
  const v = P[name];
  if (v) { try { node.setBoundVariable(field, v); return; } catch (e) {} }
  if (fallback != null) node[field] = fallback;
}
