async function buildSwatches(page) {
  const th = COLL.Theme, ac = COLL.Accent;
  const colors = DATA.collections.find((c) => c.name === "Theme").variables.filter((v) => v.t === "COLOR");
  let x = 0;
  for (const [mName, mId] of Object.entries(th.modes)) {
    const col = al("Theme · " + mName, { dir: "v", gap: 8, px: 24, py: 24, radius: "card", fill: "color/bg/page", align: "MIN", w: 360 });
    col.setExplicitVariableModeForCollection(th.coll, mId);
    col.appendChild(txt(mName, "Title 2", "color/text/primary", "Mode"));
    for (const v of colors) {
      const r = al(v.n, { gap: 12, align: "CENTER" });
      const sw = figma.createRectangle(); sw.resize(40, 40); sw.cornerRadius = 12; bindFill(sw, v.n); bindStroke(sw, "color/line/separator", 1); r.appendChild(sw);
      const tx = al("t", { dir: "v", gap: 0, align: "MIN" }); tx.appendChild(txt(v.n, "Footnote", "color/text/primary", "Name")); tx.appendChild(txt(v.css || "", "Caption 1", "color/text/secondary", "CSS")); r.appendChild(tx);
      col.appendChild(r);
    }
    page.appendChild(col); col.x = x; col.y = 0; x += 400;
  }
  let ax = 0;
  for (const [mName, mId] of Object.entries(ac.modes)) for (const [tName, tId] of [["Dark", th.modes.Dark], ["Light", th.modes.Light]]) {
    if (!tId) continue;
    const f = al("Accent · " + mName + " · " + tName, { dir: "v", gap: 12, px: 20, py: 20, radius: "card", fill: "color/bg/primary", align: "MIN", w: 260 });
    f.setExplicitVariableModeForCollection(th.coll, tId); f.setExplicitVariableModeForCollection(ac.coll, mId);
    f.appendChild(txt(mName + " · " + tName, "Headline", "color/text/primary", "Name"));
    const b = LIB.Button.findChild((n) => n.name === "Variant=Primary, Size=L, Content=Icon + Text, State=Default").createInstance(); f.appendChild(b);
    const t = LIB.Button.findChild((n) => n.name === "Variant=Tinted, Size=M, Content=Text, State=Default").createInstance(); f.appendChild(t);
    f.appendChild(txt("Акцентный текст", "Body", "color/accent/text", "Accent text"));
    f.appendChild(LIB.Toggle.children[0].createInstance());
    page.appendChild(f); f.x = ax; f.y = 1700; ax += 290;
  }
}

