function grow(n) { try { n.layoutGrow = 1; } catch (e) {} }
function fillH(n) { try { n.layoutSizingVertical = "FILL"; } catch (e) {} }
function wrapT(t) { fillW(t); try { t.textAutoResize = "HEIGHT"; } catch (e) {} }
function pad(f, t, r, b, l) { f.paddingTop = t; f.paddingRight = r; f.paddingBottom = b; f.paddingLeft = l; }
function fixed(f, w, h) { f.primaryAxisSizingMode = "FIXED"; f.counterAxisSizingMode = "FIXED"; f.resize(w, h); }
function circ(d, fill, ic, icSize, icColor, name) { const c = al(name || "Circle", { radius: "pill", justify: "CENTER", fill }); fixed(c, d, d); if (ic) c.appendChild(icon(ic, icSize, icColor)); return c; }
