function bone(color, pct, W, big) {
  // big — крупная косточка PosterCard: полоса 16, шишки 20
  const T = big ? 16 : 8, K = big ? 20 : 10, m = K / 2 + 2, H = T + K - 2;
  const b = figma.createFrame(); b.name = "Bone · косточка"; b.fills = []; b.resize(W, H); b.clipsContent = false;
  const ty = (H - T) / 2;
  const tr = rect("Track", W - 2 * m, T, "color/fill/3", T / 2); b.appendChild(tr); tr.x = m; tr.y = ty; tr.constraints = { horizontal: "STRETCH", vertical: "CENTER" };
  for (const [nm, x, y, c, h] of [["Knob L1", 0, 0, color, "MIN"], ["Knob L2", 0, H - K, color, "MIN"], ["Knob R1", W - K, 0, "color/fill/3", "MAX"], ["Knob R2", W - K, H - K, "color/fill/3", "MAX"]]) {
    const e = figma.createEllipse(); e.name = nm; e.resize(K, K); bindFill(e, c); b.appendChild(e); e.x = x; e.y = y; e.constraints = { horizontal: h, vertical: "CENTER" };
  }
  const fl = rect("Fill · ширина = доля", Math.round((W - 2 * m) * pct), T, color, T / 2); b.appendChild(fl); fl.x = m; fl.y = ty; fl.constraints = { horizontal: "SCALE", vertical: "CENTER" };
  return b;
}
