function searchPill(v) { const f = al("Search", { gap: 8, px: 12, radius: "pill", fill: "color/fill/2" }); f.minHeight = 44; f.appendChild(icon("search", 20, "color/text/secondary")); f.appendChild(txt(v, "Body", "color/text/primary", "Value")); return f; }
