async function buildMedKit(page, y0) {
  let y = y0;
  const title = (s, sub) => { const t = txt(s, "Title 1", "color/text/primary", "Section"); place(page, t, 0, y); y += 44; if (sub) { const u = txt(sub, "Subheadline", "color/text/secondary", "Note"); place(page, u, 0, y); y += 32; } y += 12; };
  title("Медицинский слой", "LabResultRow · LabChart v2 · ChartLegend · PrescriptionCard · VisitRow · DiagnosisRow · ClinicPicker. Отклонение — словом и стрелкой, время забора — формой маркера.");
  const lr = []; for (const d of ["Below", "Normal", "Above", "None"]) for (const m of ["le4", "mid", "gt8", "unknown", "none"]) lr.push(labRow(d, m));
  LIB.LabRow = set("LabResultRow", lr, page, 0, y, 2000); for (const p of ["Name", "Norm", "Value", "Unit", "Hours"]) textProp(LIB.LabRow, p, p);
  y += LIB.LabRow.height + 40;
  LIB.LabChart = place(page, labChart(), 0, y);
  LIB.Legend = place(page, legendRow(), 420, y);
  LIB.Rx = place(page, prescriptionCard(), 420, y + 120);
  LIB.Diagnosis = set("DiagnosisRow", ["Confirmed", "Hypothesis", "Removed"].map(diagnosisRow), page, 840, y, 460);
  LIB.Visit = set("VisitRow", ["Visit", "Online"].map(visitRow), page, 1340, y, 460);
  LIB.Clinic = place(page, clinicPicker(), 1840, y);
  y += Math.max(LIB.LabChart.height, LIB.Diagnosis.height, LIB.Clinic.height, 400) + 80;
  return y;
}
function medBlock(w, b) {
  const add = (n) => { w.appendChild(n); fillW(n); return n; };
  switch (b.k) {
    case "seg": { if (b.items.length < 3) return false; const f = al("SegmentedControl · " + b.items.length, { gap: 4, px: 4, py: 4, radius: "pill", fill: "color/fill/track" }); add(f);
      b.items.forEach((l, i) => { const s = al("Segment", { px: 12, radius: "pill", justify: "CENTER", fill: i === b.on ? "color/fill/selected" : null }); bindNum(s, "minHeight", "size/hit", 44); s.appendChild(txt(l, i === b.on ? "Subheadline Emphasized" : "Subheadline", i === b.on ? "color/text/primary" : "color/text/secondary", "Label " + (i + 1))); f.appendChild(s); grow(s); }); return true; }
    case "lab": { const g = vsp("LabGroup", 0); radius(g, "radius/card", 28); bindFill(g, "color/fill/1"); g.clipsContent = true; add(g);
      b.rows.forEach((r, i) => { if (i) { const sep = rect("Separator", 10, 1, "color/line/separator"); g.appendChild(sep); fillW(sep); }
        const inst = pick(LIB.LabRow, "Deviation=" + (DEV_N[r.dev] || "None") + ", Marker=" + r.mk); setT(inst, { Name: r.name, Norm: r.norm, Value: r.val, Unit: r.unit }); if (r.hrs) setT(inst, { Hours: r.hrs }); g.appendChild(inst); fillW(inst); }); return true; }
    case "chart": add(LIB.LabChart.createInstance()); return true;
    case "legend": add(LIB.Legend.createInstance()); return true;
    case "rx": { const i = add(LIB.Rx.createInstance()); setT(i, { Number: b.number, Detail: b.sub }); return true; }
    case "search": add(searchPill(b.value)); return true;
    case "table": { const g = vsp("Table", 0); radius(g, "radius/card", 28); bindFill(g, "color/fill/1"); g.clipsContent = true; add(g);
      [b.head, ...b.rows].forEach((cells, i) => { const r = al(i ? "Row " + i : "Head", { gap: 8, align: "MIN" }); pad(r, 12, 16, 12, 16); if (i) { bindStroke(r, "color/line/separator", 1); r.strokeTopWeight = 1; r.strokeBottomWeight = 0; r.strokeLeftWeight = 0; r.strokeRightWeight = 0; }
        cells.forEach((c) => { const t = txt(c, i ? "Subheadline Emphasized" : "Footnote", i ? "color/text/primary" : "color/text/secondary", "Cell"); r.appendChild(t); grow(t); }); g.appendChild(r); fillW(r); }); return true; }
  }
  return false;
}

// ---------- run ----------
async function getPage(name) {
  await figma.loadAllPagesAsync();
  let p = figma.root.children.find((x) => x.name === name);
  if (!p) { p = figma.createPage(); p.name = name; }
  return p;
}
(async () => {
  try {
    figma.notify("Graphite: переменные…", { timeout: 2000 });
    await buildVariables();
    await loadFonts();
    await buildStyles();
    const comps = await getPage("Components");
    await figma.setCurrentPageAsync(comps);
    comps.children.slice().forEach((n) => n.remove());
    figma.notify("Graphite: компоненты…", { timeout: 2000 });
    await buildComponents(comps);
    const vars = await getPage("Variables");
    vars.children.slice().forEach((n) => n.remove());
    await buildSwatches(vars);
    const tg = await getPage("Togo · компоненты");
    await figma.setCurrentPageAsync(tg);
    tg.children.slice().forEach((n) => n.remove());
    figma.notify("Graphite: компоненты Togo…", { timeout: 2000 });
    await buildTogo(tg);
    const bd = await getPage("Togo · смелее");
    await figma.setCurrentPageAsync(bd);
    bd.children.slice().forEach((n) => n.remove());
    figma.notify("Graphite: компоненты «смелее»…", { timeout: 2000 });
    await buildBold(bd);
    const scr = await getPage("Templates");
    await figma.setCurrentPageAsync(scr);
    scr.children.slice().forEach((n) => n.remove());
    figma.notify("Graphite: экраны по размерам…", { timeout: 2000 });
    buildTemplates(scr);
    const kitP = await getPage("Togo · экраны-компоненты");
    await figma.setCurrentPageAsync(kitP);
    kitP.children.slice().forEach((n) => n.remove());
    figma.notify("Graphite: компоненты экранов…", { timeout: 2000 });
    const ky = await buildKit(kitP);
    await buildMedKit(kitP, ky);
    const allP = await getPage("Screens · все экраны");
    await figma.setCurrentPageAsync(allP);
    allP.children.slice().forEach((n) => n.remove());
    figma.notify("Graphite: все экраны чистовика (" + SCREENS_SPEC.reduce((a, s) => a + s.frames.length, 0) + ")…", { timeout: 3000 });
    await buildScreens(allP);
    figma.viewport.scrollAndZoomIntoView(allP.children);
    const n = Object.keys(P).length;
    figma.closePlugin("Graphite v5: " + n + " переменных, " + Object.keys(TS).length + " стилей, " + Object.keys(LIB).length + " наборов компонентов." + (log.length ? " Внимание: " + log.join(" ") : ""));
  } catch (e) {
    figma.closePlugin("Graphite: ошибка — " + (e && e.message ? e.message : e) + (log.length ? " · " + log.join(" ") : ""));
  }
})();
